echo "K1: dpofix7"; export RUNNER_TRACKING_ID=""
N=/workspace/nox; D=$N/ops/dpo; A=$N/agent/autotrain; ST=$N/state/p3; ts=$(date +%s); W=$(mktemp -d)
base64 -d > $W/char_cycle.sh <<'B64'

B64
bash -n $W/char_cycle.sh || { echo SYNTAX_FAIL; exit 0; }
cp -a $D/char_cycle.sh $D/char_cycle.sh.bak_fix7_$ts; cp $W/char_cycle.sh $D/char_cycle.sh
# гибрид с большим n-cpu-moe для окна обучения (больше VRAM под тренер, чтобы уложиться в 92%)
sed 's/--n-cpu-moe 22/--n-cpu-moe 36/' $A/donor_hybrid.cmd.liska_ncmoe22 > $A/donor_hybrid.cmd.dpo_ncmoe36
echo "cmd36 ncmoe_tokens=$(grep -o -- '--n-cpu-moe 36' $A/donor_hybrid.cmd.dpo_ncmoe36 | wc -l) 22_left=$(grep -c -- '--n-cpu-moe 22' $A/donor_hybrid.cmd.dpo_ncmoe36)"
rm -f $ST/dpo_vram_abort; [ -f $ST/dpo_pending.hold_q27b ] && mv $ST/dpo_pending.hold_q27b $ST/dpo_pending; touch $ST/dpo_pending
for P in $(pgrep -f 'bash .*char_cycle.sh|python -I train_dpo.py'); do kill -9 $P; done; sleep 3
echo "lock_free=$(flock -n $D/char_cycle.lock true && echo 1 || echo 0)"
cd $D && setsid nohup bash $D/char_cycle.sh >> $A/char_cycle.log 2>&1 < /dev/null &
for i in $(seq 8); do sleep 30; pgrep -f 'python -I train_dpo.py' >/dev/null && break; done; sleep 90
UM=$(nvidia-smi --query-gpu=memory.used,memory.total --format=csv,noheader,nounits); echo "vram $UM pct=$(( ${UM%%,*}*100/${UM##*, } )) 8104=$(curl -s -o /dev/null -m 5 -w %{http_code} http://127.0.0.1:8104/health) trainer=$(pgrep -fc 'python -I train_dpo.py') body_moe=$(P=$(pgrep -f 'llama-server.*8104' | head -1); tr '\0' ' ' </proc/$P/cmdline | grep -o -- '--n-cpu-moe [0-9]*' | awk '{print $2}')"
tail -4 $A/char_cycle.log | cut -c1-150
rm -rf $W; echo END
